// ===================== Trạng thái nhiệt độ hiện tại =====================
static uint8_t currentTemp = AC_TEMP_DEFAULT; // mặc định 25°C

// ===================== Helper =====================
#define RAW_LEN(arr) (sizeof(arr) / sizeof(arr[0]))

static void sendTempRaw(uint8_t temp) {
    if (temp < AC_TEMP_MIN || temp > AC_TEMP_MAX) return;
    uint8_t idx = temp - AC_TEMP_MIN;
    sendRaw(acTempTable[idx], acTempTableLen[idx]);
    Serial.print("[AC] Nhiet do: ");
    Serial.print(temp);
    Serial.println(" C");
}
// ===================== Điều hòa =====================
void On_AC() {
    sendRaw(rawData_ac_on, RAW_LEN(rawData_ac_on));
    Serial.println("[AC] Bat dieu hoa");
}
void Off_AC() {
    sendRaw(rawData_ac_off, RAW_LEN(rawData_ac_off));
    Serial.println("[AC] Tat dieu hoa");
}
uint8_t AC_Get_Temp() {
    return currentTemp;
}
void AC_Set_Temp(uint8_t temp) {
    if (temp < AC_TEMP_MIN || temp > AC_TEMP_MAX) {
        Serial.print("[AC] Nhiet do phai tu ");
        Serial.print(AC_TEMP_MIN);
        Serial.print(" den ");
        Serial.print(AC_TEMP_MAX);
        Serial.println(" C");
        return;
    }
    currentTemp = temp;
    sendTempRaw(currentTemp);
}

void AC_Temp_Up() {
    if (currentTemp >= AC_TEMP_MAX) {
        Serial.print("[AC] Da o muc cao nhat: ");
        Serial.print(AC_TEMP_MAX);
        Serial.println(" C");
        return;
    }
    currentTemp++;
    sendTempRaw(currentTemp);
}

void AC_Temp_Down() {
    if (currentTemp <= AC_TEMP_MIN) {
        Serial.print("[AC] Da o muc thap nhat: ");
        Serial.print(AC_TEMP_MIN);
        Serial.println(" C");
        return;
    }
    currentTemp--;
    sendTempRaw(currentTemp);
}

